INSERT INTO writing_lessons (lesson, scope, status, origin, decided_at) VALUES
('Write in your own words and your own order. Never reuse a source''s sentence, even with a few words changed: restate the point. Only fixed names, terms and figures may match the source.', 'all', 'approved', 'chat', NOW()),
('Do not say what people "often call" something, or that there is "only one" of something, unless a source says so.', 'all', 'approved', 'chat', NOW()),
('A section must add something the figure cards do not. Leave out a section that only restates the dates or notes already on the cards, and do not refer to "the cards on this page": the text must make sense on its own.', 'all', 'approved', 'chat', NOW());
